import numpy as np
from scipy.optimize import linear_sum_assignment

class Solver:
    def solve(self, problem, **kwargs):
        M = np.asarray(problem['cost_matrix'])
        a = np.asarray(problem['source_weights'])
        b = np.asarray(problem['target_weights'])
        # The benchmark instances have equal, uniform marginals, reducing OT to
        # the linear assignment problem.
        if M.shape[0] == M.shape[1] and np.all(a == a[0]) and np.all(b == b[0]) and abs(a[0]-b[0]) < 1e-15:
            rows, cols = linear_sum_assignment(M)
            G = np.zeros(M.shape, dtype=float)
            G[rows, cols] = a[0]
            return {'transport_plan': G}
        # General fallback
        import ot
        return {'transport_plan': ot.lp.emd(a, b, np.ascontiguousarray(M, dtype=np.float64), check_marginals=False)}
